# One-off migration record: factual additions to the original published policies.
# Public operator identity and precise provider retention periods were not supplied;
# this update deliberately does not invent them.
from pathlib import Path
import re,json
snap=Path('/tmp/inventoryos-policy-originals');snap.mkdir(exist_ok=True)
for name in ['privacy','terms','refunds','cookies','data-security']:
 p=Path(name+'.html');(snap/p.name).write_text(p.read_text())

def article(id,title,body):return f'<article class="legal-card" id="{id}"><h2>{title}</h2>{body}</article>'
def update(name,replacements,additions,anchor=None):
 p=Path(name+'.html');s=p.read_text()
 for old,new in replacements:
  if old not in s:raise RuntimeError(f'Missing original wording in {name}: {old[:80]}')
  s=s.replace(old,new)
 blocks='\n'.join(article(*a) for a in additions)
 if anchor:
  mark=f'<article class="legal-card" id="{anchor}">';assert mark in s;s=s.replace(mark,blocks+'\n'+mark,1)
 else:
  # Place additions at the end of legal-content, before the layout closing divs.
  marker='                </div>\n            </div>\n        </section>\n    </main>'
  assert marker in s;s=s.replace(marker,blocks+'\n'+marker,1)
 for id,title,body in additions:
  toc=f'<a href="#{id}">{title}</a>\n'
  s=s.replace('                </aside>',toc+'                </aside>',1)
 counter=[0]
 def number(m):counter[0]+=1;return '<h2>'+str(counter[0])+'. '+re.sub(r'^\d+\.\s*','',m.group(1))+'</h2>'
 s=re.sub(r'<h2>(.*?)</h2>',number,s,flags=re.S)
 s=s.replace('Last updated: 10 July 2026','Last updated: 22 October 2026')
 p.write_text(s)

update('privacy',[
 ('InventoryOS is inventory, sales, expenses, barcode, dispatch and printing software for resellers.','InventoryOS provides inventory, sales, expenses, barcode, dispatch and printing tools for resellers, Manufacturing mode for small manufacturers, and a separate InventoryOS Retail service for shops and service businesses.'),
 ('Where we rely on consent, for example for non-essential cookies if added later, you can withdraw that consent.','For optional InventoryOS marketing emails, we rely on your separate opt-in consent, which you can withdraw. Marketing consent is not a condition of creating an account. Contract and legitimate interests support necessary account, security, support and requested service messages; legal obligations can require us to keep certain billing records.'),
 ('<li><strong>Hosting, database, storage and security providers</strong> used to operate the service.</li>','<li><strong>Cloudflare</strong> for website delivery, routing and security, alongside database, storage and infrastructure services used to operate InventoryOS.</li>'),
 ],[
 ('retail-and-manufacturing','Retail, manufacturing and support records','''<p>Manufacturing records include materials and measurements, recipes, source and finished batches, expiry and recall status, equipment usage, maintenance history and saved timer deadlines.</p><p>Retail records include business and shop display names, product and service catalogues, suppliers, prices and costs, stock events, sales, receipts, returns, cash movements, counts, wastage, staff assignments and management approvals. Staff numbers and protected PIN credentials are used for till access; private PINs are not printed on staff QR cards or receipts. The cashier’s number can appear on receipts and sale records.</p><p>If a shop uses customer tools, its records may include customer names and contact details, loyalty identifiers and QR cards, purchase history, bookings, preorders, collections and deposits. Customer email receipt requests include the recipient email address, sale information, delivery state and billable sending usage. Resend delivers these transactional receipts using the shop display name and a configured verified sending address. Receiving a shop receipt does not subscribe the customer to InventoryOS marketing.</p><p>Help requests record the signed-in account email, selected workspace, topic, message, timestamps and support status. They are available to authorised support administrators and are also sent to the support email inbox. Archiving a request marks it complete; it does not itself delete it.</p>'''),
 ('marketing','Optional marketing and service emails','''<p>When you choose the mailing-list opt-in, we record your choice and may use your account email to send product updates, feature announcements, feedback requests and relevant offers about InventoryOS. You can ask to be removed by emailing <a href="mailto:hello@inventoryos.co.uk">hello@inventoryos.co.uk</a> or use an unsubscribe option where supplied. We keep enough preference information to honour an opt-out.</p><p>We do not sell or give your mailing-list details to unrelated organisations for their own marketing. Service providers such as Resend may process them on our behalf to deliver our emails. Necessary account verification, password reset, billing, support, receipt and requested operational reminder messages are separate from optional marketing.</p>'''),
 ('customer-record-responsibilities','When you upload other people’s information','''<p>The business operating a workspace or Retail shop is responsible for the customer, employee, supplier and recipient information it chooses to enter. It should provide its own privacy information, identify an appropriate lawful basis, restrict staff access and respond to requests concerning its business records. InventoryOS processes those workspace records to provide the service to that business. Contact us about data-processing arrangements or assistance with a request.</p><p>We are responsible for our own account administration, subscription, security, support and optional InventoryOS marketing activities. Do not upload unnecessary sensitive information, payment-card security codes or passwords belonging to customers or suppliers.</p>'''),
 ('browser-copies-and-exports','Local copies, store deletion and exports','''<p>Retail PWAs may keep operational snapshots and pending cash sales in browser storage on the device used. Unsynced data stays on that device until a successful sync; clearing site data or losing the device can remove that copy. Use device access controls and shared-device sign-out or till locking.</p><p>Store deletion is a separate owner-controlled action. Its workflow requires an emailed CSV backup and confirmation before permanent deletion. The backup is sent to the verified account login email and can contain customer, sales and other business records. Products have their own CSV; login credentials and staff PINs are excluded. Keep emailed exports secure and sync every device before deleting a store. Your account, other shops and shared staff are not deleted by deleting one store.</p><p>Subscription cancellation alone does not delete business records. Some billing, security, legal and deletion-audit information may need to remain after operational data is removed. Provider-held email copies, delivered attachments and your own exports are not erased by deleting an app record.</p>'''),
 ('international-processing','Provider locations and transfers','''<p>Our email, payment, delivery and infrastructure providers may process information outside the UK. UK data protection requirements apply to those transfers. Contact <a href="mailto:hello@inventoryos.co.uk">hello@inventoryos.co.uk</a> for details of the relevant providers, processing locations and applicable transfer arrangements.</p><p>We do not use solely automated decisions about people that produce legal or similarly significant effects. Stock alerts, price suggestions and production calculations are operational aids that users review.</p>''')
 ],'changes')

update('terms',[
 ('InventoryOS provides inventory, stock location, sales, expenses, refunds, barcode, dispatch, shipping-label email import and optional direct printing tools for resellers. Features may vary by plan and may change over time.','InventoryOS provides inventory, stock location, sales, expenses, refunds, barcode, dispatch, shipping-label email import and optional direct printing tools for resellers; optional Manufacturing mode on Business; and a separate InventoryOS Retail service for shops and service businesses. Features vary by subscription and enabled settings.'),
 ('We may update, add, remove or change features, plans and limits as the product develops.','We may update, add, remove or change features, plans and limits as the product develops. Material price or contractual changes will be communicated before they apply where required; any price change is subject to the relevant billing notice and your cancellation rights.'),
 ('To the maximum extent permitted by law, we are not liable for indirect loss, lost profits, lost sales, marketplace issues, incorrect user-entered data, printer errors or business decisions made using the service.','For business use, to the extent permitted by law, we are not liable for indirect or consequential loss, lost profits, lost sales, marketplace issues, incorrect user-entered data, printer errors or business decisions made using the service. Nothing in these terms excludes liability for death or personal injury caused by negligence, fraud or fraudulent misrepresentation, or any liability or statutory consumer rights that cannot lawfully be excluded.'),
 ],[
 ('retail-billing','Retail shops and optional add-ons','''<p>InventoryOS Retail is separate from Free, Starter, Pro and Business reseller/manufacturing workspaces, stock and billing. Each subscribed Retail shop currently costs £19.99/month and includes unlimited tills and staff. Additional subscribed shops are charged separately, with their own billing periods. Creating an unactivated shop does not itself start paid billing.</p><p>Printed Retail receipts are included. Customer email receipts require a separately activated paid add-on. The current introductory charge is £2.99 for the first 30 days. Subsequent periods are billed monthly in arrears by successful sending usage: 0–1,000 sends £2.99; 1,001–5,000 £4.99; 5,001–10,000 £9.99; 10,001–25,000 £19.99. The service currently limits sends to 25,000 per billing period. Usage already incurred remains payable when cancelling. Review the live checkout and Stores &amp; billing details before purchase; sandbox activity does not create a live subscription.</p><p>Pro and Business reorder email reminders are a separate optional £1.99/month add-on. These are different from customer email receipts and Retail’s included daily reorder emails. Optional add-ons are not activated simply by creating an account.</p>'''),
 ('trials','Complimentary Business trials','''<p>A one-week Business trial can be requested by emailing us after creating an account. It is activated manually, not automatically on every registration. The app displays its expiry and the plan to which access returns. A complimentary trial does not by itself create a new paid subscription. Existing subscriptions and add-ons continue on their own terms unless you cancel them. When the trial ends, lower-plan feature and stock limits apply again.</p>'''),
 ('retail-payments','Till payments, staff and offline records','''<p>InventoryOS currently records card payments that your staff confirm after using your separate terminal. It does not trigger the terminal, verify settlement or move the sale proceeds. Your payment provider’s contract and fees are separate. You remain responsible for checking the terminal result, cash received, change, refunds, permissions, float and closing balance.</p><p>Staff should use their own number or QR and private PIN. Only authorised managers should approve restricted actions. You control staff assignments and shop access. Restricted staff tills require internet access. Prepared back-office cash sales may be queued on the original device and synced after reconnecting; they are not a guarantee of uninterrupted offline trading. Do not clear browser data or delete a shop while sales are pending.</p>'''),
 ('manufacturing-and-automation','Manufacturing, catalogues and suggested decisions','''<p>Manufacturing mode is off by default and requires Business. You are responsible for recipes, measurement units, safe production, finished quantities, batch and expiry details, recalls and any regulatory records your business needs. Confirm actual completion before recording production. Saved timers do not themselves make products, complete cleaning or deduct stock.</p><p>Barcode catalogue matches, carrier detection, cropped labels, supplier price checks, reorder quantities and suggested selling prices can be incomplete or incorrect. Check them before use. Supplier pages and public catalogue coverage may change or be unavailable. Use supplier links lawfully; do not upload supplier account passwords. The service is not a guarantee of product safety, regulatory compliance, stock availability or profit.</p>'''),
 ('store-deletion','Exports and permanent shop deletion','''<p>Before permanently deleting a Retail shop, sync pending sales, finish transactions, log staff out, balance and close tills, and receive and save the CSV backup sent to the verified login email. The owner must confirm the backup and type the required deletion text. Products, sales, customers, orders and other store-specific records are permanently removed; other shops, the account and shared staff remain. You are responsible for retaining records required for your business.</p><p>The deletion workflow stops that shop’s and its email-receipt subscription’s future renewals at the end of the current periods. Existing charges and usage remain payable. Deleting data does not undo payments already made or guarantee immediate erasure of provider-held billing records or email backups.</p>'''),
 ('consumer-rights','Statutory rights and policy documents','''<p>The <a href="refunds.html">Refund &amp; Cancellation Policy</a>, <a href="privacy.html">Privacy Policy</a>, <a href="cookies.html">Cookie Policy</a> and <a href="data-security.html">Data &amp; Security page</a> explain the corresponding parts of the service. Nothing in these terms removes rights you have under applicable consumer or data protection law. Merely signing up or starting to use the app does not automatically waive a statutory cancellation right.</p>''')
 ],'contact')

update('refunds',[
 ('Monthly subscription fees are generally non-refundable once a billing period has started, except where required by law or where we choose to offer a goodwill refund.','For business subscriptions, monthly fees are generally non-refundable once a billing period has started, except where required by law, for a billing error or where we offer a goodwill refund. This does not override the consumer cancellation or other statutory rights described below.'),
 ],[
 ('separate-subscriptions','Separate shops, plans and add-ons','''<p>Manage reseller/manufacturing subscriptions and the £1.99 reorder email add-on through Settings and the relevant Stripe billing portal. Manage each Retail shop and its separate email-receipt add-on through Retail → Stores &amp; billing. Cancelling one shop or add-on does not cancel your other shops, add-ons or InventoryOS plan. Check each confirmation and next-renewal date.</p><p>Retail currently costs £19.99/month per subscribed shop with unlimited tills and staff. Email receipts currently cost £2.99 for the first 30 days, then monthly in arrears at £2.99 for 0–1,000 sends, £4.99 for 1,001–5,000, £9.99 for 5,001–10,000 or £19.99 for 10,001–25,000. Cancelling stops future renewal according to the confirmation; it does not erase accrued sending usage or other amounts already due.</p><p>If the portal is unavailable or an access limit prevents you managing billing, email <a href="mailto:hello@inventoryos.co.uk">hello@inventoryos.co.uk</a> from your account email with the subscription or shop concerned and your request. Keep the cancellation confirmation.</p>'''),
 ('consumer-cancellation','Consumer cancellation and service rights','''<p>InventoryOS is designed for business use. If you contract as a consumer and applicable law gives you a cancellation right for an online service, you can normally cancel within 14 days after the contract is made without giving a reason. Email us a clear statement of your decision, identifying your account and subscription. You do not have to use a particular form.</p><p>If you expressly request that a service begins during that period, a proportionate charge for service supplied before cancellation may apply only where the required information and consent conditions have been met. Use of the app alone is not treated as an automatic waiver. Any applicable rights where the service is faulty, not as described or not supplied with reasonable care and skill remain unaffected.</p><p>Where a statutory cancellation refund is due, we will make it within the applicable legal deadline, normally within 14 days after being told of the cancellation, to the original payment method unless otherwise agreed. Bank or card processing time can affect when it appears. Statutory refunds are not discretionary case-by-case goodwill decisions.</p><p><strong>Optional cancellation wording:</strong> “I give notice that I cancel my InventoryOS subscription. Account email: [your email]. Subscription or shop: [details]. Contract or order date: [date]. Your name and date of notice: [details].” Send it to <a href="mailto:hello@inventoryos.co.uk">hello@inventoryos.co.uk</a>.</p>'''),
 ('trial-end','End of a free Business trial','''<p>The manually granted one-week Business trial does not itself create a new paid subscription. At its displayed end time, access returns to the stated prior plan. Existing paid subscriptions continue unless separately cancelled. Features and stock usage above the returning plan’s limits may be restricted. No subscription refund arises from complimentary access itself because no trial fee was paid.</p>'''),
 ('deletion-and-retail-sales','Deleting a shop and refunds to your own customers','''<p>Deleting a Retail shop is different from cancelling billing. The permanent deletion workflow requires an emailed CSV backup, your confirmation that it has been saved and the required deletion text. Sync every device and close tills first. The workflow stops future shop and email-receipt renewals; existing charges and usage remain payable. Save records required for tax, refunds and your own customers before deleting them.</p><p>This policy covers your purchase of InventoryOS subscriptions. It does not set your shop’s policy for customers buying goods or services from you. You remain responsible for those sales, consumer obligations and any refund through your cash process or separate card provider.</p>''')
 ])

